"""Meridian CRM RBAC permission semantics."""

_VALID_ACTIONS = {"READ", "CREATE", "UPDATE", "DELETE", "EXPORT"}


def can(
    user: dict,
    action: str,
    object: str,
    record: dict,
    role_rows: list[dict],
) -> bool:
    """Return whether the user has permission for the requested record action."""
    if action not in _VALID_ACTIONS:
        return False

    role_id = user.get("ROLE_ID", "")
    user_id = user.get("USR_ID", "")
    user_team = user.get("TEAM_CD", "")

    # Permission rows are evaluated in their supplied (legacy rule-file) order.
    permission_row = None
    for row in role_rows:
        if (
            row.get("role_id", "") == role_id
            and row.get("object", "") == object
            and row.get("action", "") == action
        ):
            permission_row = row
            break

    # ADMIN bypasses scope only; it still requires an explicit permission row.
    if permission_row is None:
        return False

    if role_id == "ADMIN":
        permitted = True
    else:
        scope = permission_row.get("scope", "")
        if scope == "ALL":
            permitted = True
        elif scope == "TEAM":
            permitted = record.get("TEAM_CD", "") == user_team
        elif scope == "OWN":
            permitted = record.get("OWNER_UID", "") == user_id
        else:
            # NONE, blank, and unsupported scope values deny access.
            permitted = False

    if not permitted:
        return False

    # Blank/missing CHAR(1) boolean values are legacy false/N values.
    if action == "DELETE":
        return record.get("DEL_FLG", "") in ("", "N")

    return True
